dtsPropsFor.Button:
/** Visual style. Defaults to "default" (solid primary). */
variant?: 'default' | 'outline' | 'secondary' | 'ghost' | 'destructive' | 'link';
/** Height + padding preset. `icon*` sizes are square. Defaults to "default" (h-8). */
size?: 'default' | 'xs' | 'sm' | 'lg' | 'icon' | 'icon-xs' | 'icon-sm' | 'icon-lg';
children?: React.ReactNode;
className?: string;
disabled?: boolean;
type?: 'button' | 'submit' | 'reset';
onClick?: React.MouseEventHandler<HTMLButtonElement>;
/** base-ui escape hatch: render the button as another element. */
render?: React.ReactElement;
'aria-label'?: string;

dtsPropsFor.Input:
type?: 'text' | 'email' | 'password' | 'number' | 'search' | 'url' | 'tel' | 'date' | 'file';
value?: string | number;
defaultValue?: string | number;
placeholder?: string;
name?: string;
id?: string;
disabled?: boolean;
required?: boolean;
readOnly?: boolean;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
className?: string;
/** Set true to show the destructive/error ring. */
'aria-invalid'?: boolean;

dtsPropsFor.Textarea:
value?: string;
defaultValue?: string;
placeholder?: string;
rows?: number;
name?: string;
id?: string;
disabled?: boolean;
required?: boolean;
onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
className?: string;
/** Set true to show the destructive/error ring. */
'aria-invalid'?: boolean;

dtsPropsFor.Label:
/** id of the control this label describes. */
htmlFor?: string;
children?: React.ReactNode;
className?: string;

dtsPropsFor.Select:
/** Selected value (controlled). */
value?: string | string[] | null;
defaultValue?: string | string[] | null;
onValueChange?: (value: string, event?: Event) => void;
/** Allow multiple selection — `value` becomes an array. */
multiple?: boolean;
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
disabled?: boolean;
required?: boolean;
name?: string;
/** Compose SelectTrigger + SelectValue + SelectContent/SelectItem here. */
children?: React.ReactNode;

dtsPropsFor.Dialog:
open?: boolean;
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/** Trap focus and block the page behind the popup. Defaults to true. */
modal?: boolean;
/** Compose DialogTrigger + DialogPortal > DialogBackdrop + DialogPopup here. */
children?: React.ReactNode;

dtsPropsFor.MarkdownContent:
/** Markdown source. GFM tables/strikethrough and fenced code with syntax highlighting are supported. */
content: string;
/** 'sm' for card fronts (questions), 'md' for card backs (answers). Defaults to 'md'. */
size?: 'sm' | 'md';
className?: string;

dtsPropsFor.AppLogo:
/** Mark + wordmark scale. Defaults to 'md'. */
size?: 'sm' | 'md' | 'lg';
/** Show the "NeuroCards" wordmark next to the mark. Defaults to true. */
showText?: boolean;
/** When set, the logo renders as a link to this href. */
href?: string;
className?: string;

dtsPropsFor.DeckCard:
id: string;
name: string;
description: string | null;
/** Free-form subject label rendered as the uppercase pill. */
subject: string;
created_at: string;
total_cards: number;
/** Cards due now — drives the destructive count and the "Study now" CTA. */
due_count: number;
learning_count: number;
/** Drives the mastery thread (mastered_count / total_cards). */
mastered_count: number;
last_review: string | null;
/** Pre-formatted relative label, e.g. "2 days ago". */
last_studied_label: string;
/** Whether the actions dropdown is open (state lives in the parent list). */
menuOpen: boolean;
onMenuToggle: () => void;
onMenuClose: () => void;
onEdit: () => void;
onDelete: () => void;

dtsPropsFor.DashboardDeckCard:
deckId: string;
/** Any lucide-react icon component. */
icon: React.ComponentType<{ className?: string }>;
title: string;
/** Secondary line under the title, e.g. "Science · 42 cards". */
category: string;
/** 0-100; drives the 2px mastery thread. */
mastery: number;
/** Cards due now; 0 switches the CTA to the outline treatment. */
due: number;
/** Tailwind background class for the icon tile, e.g. "bg-primary/10". */
iconBg: string;
/** Tailwind text-color class for the icon, e.g. "text-primary". */
iconColor: string;

dtsPropsFor.TimelineList:
timeline: Array<{
  /** Uppercase eyebrow, e.g. "TODAY" / "TOMORROW". */
  label: string;
  deck: string;
  cards: number;
  /** Italic sub-line, e.g. "Struggling bucket · every 2 days". */
  meta: string;
  /** Tailwind background class for the timeline dot, e.g. "bg-destructive". */
  dotColor: string;
  /** Tailwind text-color class for the eyebrow, e.g. "text-primary". */
  labelColor: string;
}>;

dtsPropsFor.ActivityHeatmap:
/** One entry per day, laid out in 7 rows column-first. Each value must be one
 * of 0 | 10 | 20 | 30 | 40 | 60 | 90 — the primary-tint step for that day. */
cells: number[];

dtsPropsFor.BucketRow:
bucket: {
  /** Icon key: 'trending_down' | 'bar_chart' | 'done_all' | 'help'. */
  icon: string;
  /** Bucket name, e.g. "Struggling" | "Intermediate" | "Mastered". */
  name: string;
  cards: number;
  /** Human interval, e.g. "Every 2 days". */
  interval: string;
  /** Next occurrence label, e.g. "Tue, Jul 28". */
  next: string;
  /** Tailwind left-border class, e.g. "border-l-error". */
  borderColor: string;
  /** Tailwind text-color class for the icon, e.g. "text-error". */
  iconColor: string;
};

dtsPropsFor.ProgramCard:
program: {
  id: string;
  name: string;
  deck_id: string;
  deck_name: string;
  /** false renders the paused treatment (dimmed + grayscale). */
  active: boolean;
  buckets: Array<{ name: string; cards: number; intervalDays: number; next_date_label: string }>;
  sessions: Array<{ date: string; cards: number }>;
  created_at: string;
};
onNewProgram: () => void;
